arguments.new_string:
total_width = 0
iter_characters = iter(text)
last_measured_character = None
last_was_widened = False
pending_zwj = False
for character in iter_characters:
    if character in SPECIAL:
        if character == "\u200d":
            pending_zwj = True
        elif last_measured_character:
            if not last_was_widened and last_measured_character in cell_table.narrow_to_wide:
                total_width += 1
                last_was_widened = True
    else:
        if character_width := get_character_cell_size(character, unicode_version):
            if pending_zwj and last_measured_character:
                width = get_character_cell_size(last_measured_character, unicode_version)
                if last_was_widened:
                    width += 1
                total_width -= width
            last_measured_character = character
            total_width += character_width
            pending_zwj = False
            last_was_widened = False

arguments.old_string:
total_width = 0
iter_characters = iter(text)
last_measured_character = None

for character in iter_characters:
    if character in SPECIAL:
        if character == "\u200d":
            next(iter_characters)
        elif last_measured_character:
            total_width += last_measured_character in cell_table.narrow_to_wide
            last_measured_character = None
    else:
        if character_width := get_character_cell_size(character, unicode_version):
            last_measured_character = character
            total_width += character_width
